def switch_proxy_node(self):
    """切换代理节点（当下载失败时可以尝试）"""
    if self.proxy_manager:
        try:
            # 选择新的随机节点
            new_node = self.proxy_manager.select_random()
            logger.info(f"🔄 切换到新节点: {new_node.name}")

            # 更新HTTPClient的代理配置
            proxy_url = f"http://127.0.0.1:{self.proxy_manager.local_port}"
            self.client.session.proxies = {
                'http': proxy_url,
                'https': proxy_url
            }

            return True
        except Exception as e:
            logger.error(f"❌ 切换节点失败: {e}")
            return False
    return False

